insert into legal_pages (slug, title, body) values ('kvkk', 'KVKK Aydınlatma Metni', 'GeldeSat olarak 6698 sayılı Kişisel Verilerin Korunması Kanunu kapsamında veri sorumlusuyuz.
insert into legal_pages (slug, title, body) values ('uyelik', 'Üyelik Sözleşmesi', 'Bu sözleşme GeldeSat ile üye arasında elektronik ortamda kurulur.
insert into legal_pages (slug, title, body) values ('kullanim', 'Kullanım Koşulları', 'Siteyi kullanarak bu koşulları kabul etmiş sayılırsınız. İçeriklerin telif hakkı sahiplerine aittir. İlan fotoğrafları ve metinleri kopyalanamaz. Hesap paylaşımı yasaktır. Kötüye kullanım halinde hesap askıya alınır.') on conflict (slug) do nothing;
