insert into legal_pages (slug, title, body) values ('hakkimizda', 'Hakkımızda', 'GeldeSat, Türkiye''de emlak, vasıta ve ikinci el alışverişi bir araya getiren bir ilan platformudur. Amacımız güvenli, sade ve hızlı alım-satım. Merkez: Adana.') on conflict (slug) do nothing;
